// Twilio posts incoming SMS as form-encoded fields -- From is the client's number, Body is
// their message text.
const body = $json.body || $json;
const fromNumber = (body.From || '').trim();
const messageText = (body.Body || '').trim();
return { json: { from_number: fromNumber, message_text: messageText, is_valid: !!fromNumber } };

// Confirms an actual contact match (Clio's query search can return loose/fuzzy results), by
// comparing digits-only phone numbers rather than trusting the search alone.
function digitsOnly(s) { return String(s || '').replace(/\D/g, ''); }
const fromDigits = digitsOnly($('Parse Incoming Status Text').first().json.from_number);
const contacts = $json.data || [];
const match = contacts.find(c => (c.phone_numbers || []).some(p => digitsOnly(p.number).endsWith(fromDigits.slice(-10))));
return { json: { client_id: match ? match.id : null, client_name: match ? match.name : '', is_found: !!match } };

return { json: {
  recipient: $('Parse Incoming Status Text').first().json.from_number,
  message: `We couldn't match this number to a client on file. Please call our office directly and we'll help you right away.`,
} };

// Composes a plain status reply -- only facts already in Clio (matter reference, practice area,
// status), never an interpretation, prediction, or next-steps guidance. Handles zero-matter and
// multi-matter cases explicitly rather than guessing which matter the client means.
const matters = $json.data || [];
const clientName = $('Match Client By Phone Number').first().json.client_name;
let message;
if (matters.length === 0) {
  message = `Hi ${clientName}, we don't see any open matters on file for you right now. If this seems wrong, please contact our office directly.`;
} else if (matters.length === 1) {
  const m = matters[0];
  message = `Hi ${clientName}, your matter ${m.display_number} (${(m.practice_area && m.practice_area.name) || m.description}) is currently: ${m.status}. For details or questions, please contact your attorney directly.`;
} else {
  const lines = matters.map(m => `${m.display_number}: ${m.status}`).join('; ');
  message = `Hi ${clientName}, you have ${matters.length} open matters: ${lines}. For details on any of these, please contact your attorney directly.`;
}
return { json: { recipient: $('Parse Incoming Status Text').first().json.from_number, message } };

const fromEmail = $('Parse Status Request Email').first().json.from_email;
const contacts = $json.data || [];
const match = contacts.find(c => (c.email_addresses || []).some(e => String(e.address || '').toLowerCase() === fromEmail));
return { json: { client_id: match ? match.id : null, client_name: match ? match.name : '', is_found: !!match } };

return { json: {
  recipient: $('Parse Status Request Email').first().json.from_email,
  subject: 'Re: ' + ($('Parse Status Request Email').first().json.subject || 'Case status'),
  message: `We couldn't match this email address to a client on file. Please call our office directly and we'll help you right away.`,
} };

const matters = $json.data || [];
const clientName = $('Match Client By Email').first().json.client_name;
const subject = 'Re: ' + ($('Parse Status Request Email').first().json.subject || 'Case status');
let message;
if (matters.length === 0) {
  message = `Hi ${clientName},\n\nWe don't see any open matters on file for you right now. If this seems wrong, please contact our office directly.`;
} else if (matters.length === 1) {
  const m = matters[0];
  message = `Hi ${clientName},\n\nYour matter ${m.display_number} (${(m.practice_area && m.practice_area.name) || m.description}) is currently: ${m.status}.\n\nFor details or questions, please contact your attorney directly.`;
} else {
  const lines = matters.map(m => `- ${m.display_number}: ${m.status}`).join('\n');
  message = `Hi ${clientName},\n\nYou have ${matters.length} open matters:\n${lines}\n\nFor details on any of these, please contact your attorney directly.`;
}
return { json: { recipient: $('Parse Status Request Email').first().json.from_email, subject, message } };
